"use client";
import { useCallback, useEffect, useRef, useSyncExternalStore } from "react";
import { sliceTransitions, useLatency, type LatencyPhase } from "../hooks/latency";

/**
 * The states an async button can be in. They are the shared latency states
 * (hooks/latency.ts), minus the two a button has no use for: it never draws
 * a skeleton and it cannot be cancelled.
 */
export type AsyncButtonState = Extract<LatencyPhase, "idle" | "pending" | "slow" | "success" | "error">;

export type AsyncButtonEvent = "START" | "SLOW" | "RESOLVE" | "REJECT" | "RESET";

const BUTTON_STATES = ["idle", "pending", "slow", "success", "error"] as const satisfies readonly AsyncButtonState[];
const BUTTON_EVENTS = ["START", "SLOW", "RESOLVE", "REJECT", "RESET"] as const satisfies readonly AsyncButtonEvent[];

/**
 * Every legal transition, read straight from the shared latency machine.
 * Anything not listed is ignored, so a second press while pending cannot
 * start a second request and a late result cannot move a button that has
 * already reset.
 */
export const ASYNC_BUTTON_TRANSITIONS = sliceTransitions(BUTTON_STATES, BUTTON_EVENTS);

export const asyncButtonReducer = (state: AsyncButtonState, event: AsyncButtonEvent): AsyncButtonState =>
  ASYNC_BUTTON_TRANSITIONS[state][event] ?? state;

export interface AsyncButtonLabels {
  idle: string;
  pending: string;
  slow: string;
  success: string;
  error: string;
}

const DEFAULT_LABELS: AsyncButtonLabels = {
  idle: "Save changes",
  pending: "Saving",
  slow: "Still working, this is taking longer than usual",
  success: "Saved",
  error: "Failed. Press to try again",
};

export interface AsyncButtonProps {
  /** The work. Resolve for success, reject (or throw) for failure. */
  onPress: () => Promise<unknown>;
  /** Text for each state. Missing keys fall back to the defaults. */
  labels?: Partial<AsyncButtonLabels>;
  /** How long a request runs before the button says it is slow. */
  slowAfterMs?: number;
  /** How long "success" stays before the button returns to idle. */
  successHoldMs?: number;
  /** Force reduced motion on or off. Leave undefined to follow the system setting. */
  reducedMotion?: boolean;
  /** Called on every state change, with the event that caused it. */
  onStateChange?: (next: AsyncButtonState, event: AsyncButtonEvent) => void;
  className?: string;
}

const REDUCED_QUERY = "(prefers-reduced-motion: reduce)";

const subscribeReduced = (notify: () => void) => {
  const query = window.matchMedia(REDUCED_QUERY);
  query.addEventListener("change", notify);
  return () => query.removeEventListener("change", notify);
};

/** The system setting, kept live. The server snapshot is false, so first paint matches on both sides. */
export const useSystemReducedMotion = (): boolean =>
  useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(REDUCED_QUERY).matches,
    () => false
  );

const TINT: Record<AsyncButtonState, string> = {
  idle: "255,255,255",
  pending: "140,160,255",
  slow: "255,196,110",
  success: "130,220,170",
  error: "255,130,130",
};

/**
 * A button that tells the truth about waiting. It stays focusable while it
 * works, ignores presses it cannot honour, says out loud when a request is
 * slow, and offers a retry on failure. The visible state, the screen-reader
 * announcement and the colour all come from one small state machine.
 *
 * With reduced motion the moving progress bar becomes a still, partly filled
 * bar and the colour change is instant; the words carry the same information.
 *
 * @example
 * <AsyncButton onPress={() => fetch("/api/save", { method: "POST" })} />
 */
export const AsyncButton = ({
  onPress,
  labels,
  slowAfterMs = 1200,
  successHoldMs = 1600,
  reducedMotion,
  onStateChange,
  className = "",
}: AsyncButtonProps) => {
  const systemReduced = useSystemReducedMotion();
  const reduced = reducedMotion ?? systemReduced;
  const text = { ...DEFAULT_LABELS, ...labels };

  const onStateChangeRef = useRef(onStateChange);
  useEffect(() => {
    onStateChangeRef.current = onStateChange;
  }, [onStateChange]);

  const run = useCallback(() => Promise.resolve().then(onPress), [onPress]);
  const { phase, start } = useLatency({
    run,
    slowAfterMs,
    successHoldMs,
    onEvent: ({ event, to }) => onStateChangeRef.current?.(to as AsyncButtonState, event as AsyncButtonEvent),
  });
  const state = phase as AsyncButtonState;
  const press = start;

  const busy = state === "pending" || state === "slow";
  const tint = TINT[state];
  const label = text[state];

  return (
    <div className={`inline-flex flex-col items-stretch gap-2 ${className}`}>
      <style>{`
        @keyframes prism-async-slide { from { transform: translateX(-100%); } to { transform: translateX(250%); } }
      `}</style>
      <button
        type="button"
        onClick={press}
        aria-busy={busy}
        aria-disabled={busy}
        data-state={state}
        className="relative overflow-hidden rounded-xl px-6 py-3 text-sm font-medium text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-white/70 focus-visible:ring-offset-2 focus-visible:ring-offset-black"
        style={{
          background: `rgba(${tint},${state === "idle" ? 0.08 : 0.16})`,
          border: `1px solid rgba(${tint},${state === "idle" ? 0.2 : 0.5})`,
          cursor: busy ? "progress" : "pointer",
          transition: reduced ? "none" : "background 240ms, border-color 240ms",
        }}
      >
        <span className="relative z-10 block text-center">{label}</span>
        {busy && (
          <span
            aria-hidden
            className="absolute bottom-0 left-0 h-[3px]"
            style={
              reduced
                ? { width: state === "slow" ? "75%" : "40%", background: `rgb(${tint})` }
                : {
                    width: "40%",
                    background: `rgb(${tint})`,
                    animation: `prism-async-slide ${state === "slow" ? 2400 : 1100}ms linear infinite`,
                  }
            }
          />
        )}
      </button>
      {/* One polite announcement per state change; the visible label can be longer. */}
      <span role="status" aria-live="polite" className="sr-only">
        {state === "idle" ? "" : text[state]}
      </span>
    </div>
  );
};

"use client";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";

/**
 * Latency states: one honest lifecycle for anything that waits on a request.
 *
 * It is a state, not a component. The async button and the loading region
 * both run on it, and anything else that waits (a select that fetches its
 * options, a search box, a save bar) can take the same hook and get the same
 * timing rules for free:
 *
 * - pending: a request is out but under the skeleton threshold, so nothing
 *   new is drawn. A fast response never flashes a placeholder.
 * - skeleton: it has passed that threshold (only if you ask for one).
 * - slow: it has taken long enough that the interface should say so.
 * - success / error / cancelled: settled. START runs it again, RESET clears it.
 */
/** Under this, show nothing new: a fast response never flashes a placeholder. Shared by every waiting surface. */
export const QUIET_MS = 400;
/** Past this with no progress, say it is slow and offer a way out. */
export const SLOW_MS = 2000;

export type LatencyPhase = "idle" | "pending" | "skeleton" | "slow" | "success" | "error" | "cancelled";

export type LatencyEvent = "START" | "SHOW_SKELETON" | "SLOW" | "RESOLVE" | "REJECT" | "CANCEL" | "RESET";

/** Every legal transition. Anything not listed is ignored, so a late result cannot move a settled state. */
export const LATENCY_TRANSITIONS: Record<LatencyPhase, Partial<Record<LatencyEvent, LatencyPhase>>> = {
  idle: { START: "pending" },
  pending: { SHOW_SKELETON: "skeleton", SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  skeleton: { SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  slow: { RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  success: { START: "pending", RESET: "idle" },
  error: { START: "pending", RESET: "idle" },
  cancelled: { START: "pending", RESET: "idle" },
};

export const latencyReducer = (state: LatencyPhase, event: LatencyEvent): LatencyPhase =>
  LATENCY_TRANSITIONS[state][event] ?? state;

/**
 * The part of the machine one component uses: only these phases, reached
 * only by these events. A component that never shows a skeleton or never
 * cancels draws its own machine from this, and it is still the shared one.
 */
export const sliceTransitions = <P extends LatencyPhase, E extends LatencyEvent>(phases: readonly P[], events: readonly E[]) =>
  Object.fromEntries(
    phases.map((from) => [
      from,
      Object.fromEntries(
        Object.entries(LATENCY_TRANSITIONS[from]).filter(
          ([event, to]) => events.includes(event as E) && phases.includes(to as P)
        )
      ),
    ])
  ) as Record<P, Partial<Record<E, P>>>;

export const isBusy = (phase: LatencyPhase) => phase === "pending" || phase === "skeleton" || phase === "slow";

export interface LatencyLogEntry {
  /** Milliseconds since the request started (0 for START). */
  atMs: number;
  event: LatencyEvent;
  from: LatencyPhase;
  to: LatencyPhase;
}

export interface LatencyOptions<T> {
  /** The request. Honour `signal` if you can; late results are ignored either way. */
  run: (signal: AbortSignal) => Promise<T>;
  /** Show a skeleton after this long. Leave undefined to never show one. */
  skeletonAfterMs?: number;
  /** Say it is slow after this long. */
  slowAfterMs?: number;
  /** Return to idle this long after success. Leave undefined to stay on success. */
  successHoldMs?: number;
  /** Every real state change, with time since the request started. */
  onEvent?: (entry: LatencyLogEntry) => void;
}

/**
 * Run a request through the latency states.
 *
 * @example
 * const { phase, start } = useLatency({ run: (signal) => fetch("/api", { signal }), slowAfterMs: 1500 });
 */
export const useLatency = <T>({ run, skeletonAfterMs, slowAfterMs = SLOW_MS, successHoldMs, onEvent }: LatencyOptions<T>) => {
  const [phase, dispatch] = useReducer(latencyReducer, "idle");
  const phaseRef = useRef<LatencyPhase>("idle");
  const [data, setData] = useState<{ value: T } | null>(null);
  const [error, setError] = useState("");
  const [elapsedS, setElapsedS] = useState(0);

  const requestId = useRef(0);
  const startedAt = useRef(0);
  const timers = useRef<number[]>([]);
  const ticker = useRef<number | null>(null);
  const controller = useRef<AbortController | null>(null);
  const mounted = useRef(true);
  const onEventRef = useRef(onEvent);
  useEffect(() => {
    onEventRef.current = onEvent;
  }, [onEvent]);

  const stopTimers = () => {
    timers.current.forEach((t) => window.clearTimeout(t));
    timers.current = [];
    if (ticker.current !== null) window.clearInterval(ticker.current);
    ticker.current = null;
  };

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      stopTimers();
      controller.current?.abort();
    };
  }, []);

  /** Dispatch only legal events, and report real changes. */
  const send = useCallback((event: LatencyEvent) => {
    const from = phaseRef.current;
    const to = latencyReducer(from, event);
    if (to === from) return false;
    phaseRef.current = to;
    dispatch(event);
    const atMs = event === "START" ? 0 : Math.round(performance.now() - startedAt.current);
    onEventRef.current?.({ atMs, event, from, to });
    return true;
  }, []);

  const start = useCallback(() => {
    if (isBusy(phaseRef.current)) return;
    stopTimers();
    startedAt.current = performance.now();
    if (!send("START")) return;
    const id = ++requestId.current;
    const ctl = new AbortController();
    controller.current = ctl;
    const live = () => mounted.current && id === requestId.current;

    if (skeletonAfterMs !== undefined) {
      timers.current.push(window.setTimeout(() => live() && send("SHOW_SKELETON"), skeletonAfterMs));
    }
    timers.current.push(
      window.setTimeout(() => {
        if (!live()) return;
        send("SLOW");
        const tick = () => setElapsedS(Math.floor((performance.now() - startedAt.current) / 1000));
        tick();
        ticker.current = window.setInterval(tick, 250);
      }, slowAfterMs)
    );

    Promise.resolve()
      .then(() => run(ctl.signal))
      .then(
        (value) => {
          if (!live()) return;
          stopTimers();
          setData({ value });
          send("RESOLVE");
          if (successHoldMs !== undefined) {
            timers.current.push(window.setTimeout(() => live() && send("RESET"), successHoldMs));
          }
        },
        (err: unknown) => {
          if (!live()) return;
          stopTimers();
          setError(err instanceof Error ? err.message : "Request failed");
          send("REJECT");
        }
      );
  }, [run, send, skeletonAfterMs, slowAfterMs, successHoldMs]);

  const cancel = useCallback(() => {
    if (!isBusy(phaseRef.current)) return;
    requestId.current++; // a late result can no longer move the state
    stopTimers();
    controller.current?.abort();
    send("CANCEL");
  }, [send]);

  const reset = useCallback(() => {
    requestId.current++;
    stopTimers();
    send("RESET");
  }, [send]);

  return { phase, busy: isBusy(phase), data, error, elapsedS, start, cancel, reset };
};

"use client";
import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { Check, ChevronRight, Copy, RotateCcw, Square, X } from "lucide-react";
import { reducedMotionNow } from "../hooks/reduced-motion";
import type { AssistantPhase, Source, ToolStep } from "../hooks/assistant";

export interface AIResponseProps {
  /** Where the response is, from `useAssistant`. */
  phase: AssistantPhase;
  /** Everything that has arrived so far. */
  text: string;
  /** Tool calls in the order they were made. */
  steps: ToolStep[];
  /** Sources the tools returned. Only the ones the text cites are listed. */
  sources: Source[];
  /** Seconds since anything arrived, once that is past the slow threshold; 0 otherwise. */
  stalledS?: number;
  /** Shown when the response fails. */
  error?: string;
  onStop?: () => void;
  onRetry?: () => void;
  /** Who is answering. Default: "Assistant" */
  name?: string;
  className?: string;
}

const STEP_LABEL: Record<string, (args: Record<string, unknown>) => string> = {
  search_components: (a) => `Searched components for “${String(a.query ?? "")}”`,
  get_component: (a) => `Opened ${String(a.slug ?? "a component")}`,
};
const stepLabel = (s: ToolStep) => STEP_LABEL[s.name]?.(s.args) ?? s.name.replace(/_/g, " ");

const STATUS: Partial<Record<AssistantPhase, string>> = {
  thinking: "Thinking",
  tool: "Using a tool",
  stopped: "Stopped",
  done: "Done",
};

/** Paragraphs, `code`, **bold** and [n] citations, the only formatting an answer here needs. */
const renderText = (text: string, sources: Source[], caret: ReactNode) =>
  text
    .split(/\n{2,}/)
    .filter((p) => p.trim())
    .map((para, i, all) => (
      <p key={i} className="mt-3 first:mt-0">
        {para.split(/(\[\d+\]|`[^`]+`|\*\*[^*]+\*\*)/g).map((part, j): ReactNode => {
          const cite = part.match(/^\[(\d+)\]$/);
          if (cite) {
            const source = sources.find((s) => s.n === Number(cite[1]));
            // A number with no source behind it is shown as plain text, never as a link.
            if (!source) return part;
            return (
              <sup key={j} className="mx-0.5">
                <a
                  href={source.href}
                  aria-label={`Source ${source.n}: ${source.title}`}
                  className="rounded px-1 font-mono text-[10px] text-white/70 ring-1 ring-white/20 hover:text-white hover:ring-white/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70"
                >
                  {source.n}
                </a>
              </sup>
            );
          }
          if (part.startsWith("`") && part.endsWith("`") && part.length > 2)
            return (
              <code key={j} className="rounded bg-white/[0.07] px-1 py-0.5 font-mono text-[12px] text-white/85">
                {part.slice(1, -1)}
              </code>
            );
          if (part.startsWith("**") && part.endsWith("**") && part.length > 4) return <strong key={j} className="font-medium text-white">{part.slice(2, -2)}</strong>;
          return part;
        })}
        {i === all.length - 1 && caret}
      </p>
    ));

const StepRow = ({ step }: { step: ToolStep }) => {
  const [open, setOpen] = useState(false);
  return (
    <li className="text-[12px]">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        className="flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-white/60 hover:bg-white/[0.04] hover:text-white/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/50"
      >
        <span aria-hidden="true" className="flex h-4 w-4 shrink-0 items-center justify-center">
          {step.status === "running" ? (
            <span className="h-1.5 w-1.5 rounded-full bg-white/70 motion-safe:animate-pulse" />
          ) : step.status === "done" ? (
            <Check size={13} className="text-[#86efac]" />
          ) : (
            <X size={13} className="text-[#fca5a5]" />
          )}
        </span>
        <span className="min-w-0 flex-1 truncate">
          {stepLabel(step)}
          {step.summary && <span className={step.status === "failed" ? "text-[#fca5a5]/90" : "text-white/40"}> · {step.summary}</span>}
        </span>
        <span className="sr-only">{step.status === "running" ? "running" : step.status === "done" ? "done" : "failed"}</span>
        <ChevronRight aria-hidden="true" size={12} className={`shrink-0 text-white/30 ${open ? "rotate-90" : ""}`} />
      </button>
      {open && (
        <pre className="mx-2 mb-1 mt-0.5 overflow-x-auto rounded-lg bg-white/[0.03] px-3 py-2 font-mono text-[11px] leading-relaxed text-white/55">
          {JSON.stringify({ tool: step.name, arguments: step.args }, null, 2)}
        </pre>
      )}
    </li>
  );
};

/**
 * An AI response that is honest about where it is. Each state reads
 * differently, and none of them pretends:
 *
 * - Nothing is drawn for a response that starts quickly; past the quiet
 *   window it says it is thinking.
 * - Each tool call appears as a step as it runs, with its arguments one
 *   click away, and a failed step says what failed.
 * - Text arrives in bursts and is revealed at an even, spring-smoothed pace,
 *   so it reads instead of jumping.
 * - Citations link to their sources, and a number with no source behind it
 *   is never turned into a link.
 * - When nothing has arrived for a while it says so, with the time and a Stop.
 *   Stopping keeps what arrived. A failure keeps it too, and offers Retry.
 *
 * Screen readers hear the finished answer once, not every token.
 *
 * @example
 * const a = useAssistant();
 * <AIResponse {...a} onStop={a.stop} onRetry={() => a.start(source)} />
 */
export const AIResponse = ({ phase, text, steps, sources, stalledS = 0, error, onStop, onRetry, name = "Assistant", className = "" }: AIResponseProps) => {
  const [shown, setShown] = useState(0);
  const [copied, setCopied] = useState(false);
  const target = useRef(text.length);
  // Stopped or failed: show what arrived at once, so the halt is visible rather than the text typing on.
  const halted = useRef(false);
  useLayoutEffect(() => {
    target.current = text.length;
    halted.current = phase === "stopped" || phase === "error";
  });

  // Reveal at an even pace: the backlog drains a fixed share per frame, so bursts are smoothed and a long backlog still catches up fast.
  useEffect(() => {
    let raf = 0;
    let current = 0;
    let last = -1;
    const tick = () => {
      const goal = target.current;
      if (goal < current || halted.current || reducedMotionNow()) current = goal;
      else if (goal > current) current = Math.min(goal, current + Math.max(0.6, (goal - current) * 0.14));
      const n = Math.floor(current);
      if (n !== last) {
        last = n;
        setShown(n);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  const busy = phase === "waiting" || phase === "thinking" || phase === "tool" || phase === "streaming";
  const revealing = shown < text.length;
  const visible = text.slice(0, shown);
  const cited = sources.filter((s) => new RegExp(`\\[${s.n}\\]`).test(text));
  const settled = phase === "done" || phase === "stopped" || phase === "error";
  const status = stalledS > 0 && busy ? `Still working · ${stalledS}s` : phase === "error" ? (error ?? "Something went wrong") : STATUS[phase];

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      // Clipboard can be blocked; nothing else to do.
    }
  };

  // What a screen reader hears: the whole answer once it is finished, or why it stopped.
  const announcement =
    phase === "done" && !revealing ? `${name} answered: ${text}` : phase === "stopped" ? `${name} stopped.` : phase === "error" ? `${name} failed: ${error ?? ""}` : "";

  if (phase === "idle") return null;

  return (
    <article aria-label={`${name} response`} aria-busy={busy || revealing} className={`min-w-0 rounded-2xl border border-white/[0.08] bg-white/[0.02] p-5 ${className}`}>
      <header className="flex items-center gap-2.5">
        <span aria-hidden="true" className={`h-2 w-2 rounded-full ${busy ? "bg-white/80 motion-safe:animate-pulse" : phase === "error" ? "bg-[#fca5a5]" : "bg-white/40"}`} />
        <span className="text-[13px] text-white/80">{name}</span>
        {status && phase !== "waiting" && (
          <span className={`font-mono text-[11px] ${phase === "error" ? "text-[#fca5a5]" : "text-white/40"}`}>{status}</span>
        )}
      </header>

      {steps.length > 0 && (
        <ol aria-label="Steps" className="mt-3 grid grid-cols-[minmax(0,1fr)] gap-0.5 border-l border-white/[0.08] pl-2">
          {steps.map((s) => (
            <StepRow key={s.id} step={s} />
          ))}
        </ol>
      )}

      {visible && (
        <div className="mt-4 text-[14px] leading-relaxed text-white/80">
          {renderText(
            visible,
            sources,
            (busy || revealing) && <span aria-hidden="true" className="ml-0.5 inline-block h-[1.05em] w-[2px] translate-y-[3px] bg-white/60" />
          )}
        </div>
      )}

      {settled && !revealing && cited.length > 0 && (
        <div className="mt-4 border-t border-white/[0.06] pt-3">
          <p className="font-mono text-[10px] uppercase tracking-[0.16em] text-white/35">Sources</p>
          <ol className="mt-2 grid gap-1">
            {cited.map((s) => (
              <li key={s.n} className="flex items-center gap-2 text-[12px]">
                <span className="font-mono text-white/40">{s.n}</span>
                <a href={s.href} className="text-white/70 underline decoration-white/20 underline-offset-2 hover:text-white hover:decoration-white/50">
                  {s.title}
                </a>
              </li>
            ))}
          </ol>
        </div>
      )}

      <div className="mt-4 flex flex-wrap items-center gap-2">
        {busy && onStop && (
          <button
            type="button"
            onClick={onStop}
            className="inline-flex items-center gap-1.5 rounded-lg border border-white/[0.12] bg-white/[0.04] px-3 py-1.5 text-[12px] text-white/80 hover:bg-white/[0.08] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
          >
            <Square size={11} aria-hidden="true" />
            Stop
          </button>
        )}
        {settled && onRetry && (
          <button
            type="button"
            onClick={onRetry}
            className="inline-flex items-center gap-1.5 rounded-lg border border-white/[0.12] bg-white/[0.04] px-3 py-1.5 text-[12px] text-white/80 hover:bg-white/[0.08] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
          >
            <RotateCcw size={11} aria-hidden="true" />
            {phase === "done" ? "Regenerate" : "Retry"}
          </button>
        )}
        {settled && text && (
          <button
            type="button"
            onClick={copy}
            className="inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-[12px] text-white/55 hover:bg-white/[0.05] hover:text-white/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
          >
            {copied ? <Check size={11} aria-hidden="true" /> : <Copy size={11} aria-hidden="true" />}
            {copied ? "Copied" : "Copy"}
          </button>
        )}
      </div>

      <div className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {announcement}
      </div>
    </article>
  );
};

"use client";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";
import { QUIET_MS, SLOW_MS } from "./latency";

/**
 * The states of an AI response, and one source interface for where it comes from.
 *
 * The interface does not know whether a response is live or a replay: both
 * are a `StreamSource`, an async stream of events. The demo replays real
 * recordings with their real timing, so a visitor costs nothing, and a live
 * model would plug into the same hook unchanged.
 *
 * The timing rules are the latency states': nothing new is drawn for a
 * response that starts inside QUIET_MS, and once nothing has arrived for
 * SLOW_MS the response says it is still working and offers a way out.
 */

export type Source = { n: number; title: string; href: string };

export type StreamEvent =
  | { t: number; type: "text"; text: string }
  | { t: number; type: "tool_call"; id: string; name: string; args: Record<string, unknown> }
  | { t: number; type: "tool_result"; id: string; ok: boolean; summary: string; sources?: Source[] }
  | { t: number; type: "error"; message: string }
  | { t: number; type: "done" };

export type Recording = {
  id: string;
  title: string;
  prompt: string;
  /** How it was recorded, and anything injected. Shown beside the replay. */
  note: string;
  model: string;
  recordedAt: string;
  sources: Source[];
  events: StreamEvent[];
};

/** Anything that yields response events. Must stop when the signal aborts. */
export type StreamSource = (signal: AbortSignal) => AsyncIterable<StreamEvent>;

/**
 * Play a recording back at its recorded pace (scaled by `speed`), honouring
 * the abort signal between events. `cutAt` ends the stream early with an
 * error, to show a connection dropping mid-answer.
 */
export const replay =
  (recording: Recording, { speed = 1, cutAt }: { speed?: number; cutAt?: number } = {}): StreamSource =>
  (signal) => ({
    async *[Symbol.asyncIterator]() {
      const start = performance.now();
      for (const event of recording.events) {
        if (cutAt !== undefined && event.t >= cutAt) {
          await wait(start + cutAt / speed - performance.now(), signal);
          yield { t: cutAt, type: "error", message: "The connection dropped." } satisfies StreamEvent;
          return;
        }
        await wait(start + event.t / speed - performance.now(), signal);
        if (signal.aborted) return;
        yield event;
      }
    },
  });

const wait = (ms: number, signal: AbortSignal) =>
  new Promise<void>((resolve) => {
    if (ms <= 0 || signal.aborted) return resolve();
    const timer = window.setTimeout(resolve, ms);
    signal.addEventListener("abort", () => {
      window.clearTimeout(timer);
      resolve();
    }, { once: true });
  });

export type AssistantPhase =
  /** Nothing asked yet. */
  | "idle"
  /** Asked, inside the quiet window: nothing new is drawn. */
  | "waiting"
  /** Past the quiet window with nothing back yet. */
  | "thinking"
  /** A tool is running. */
  | "tool"
  /** Text is arriving. */
  | "streaming"
  | "done"
  /** Stopped by the user. What arrived is kept. */
  | "stopped"
  | "error";

export type ToolStep = {
  id: string;
  name: string;
  args: Record<string, unknown>;
  status: "running" | "done" | "failed";
  summary?: string;
};

type State = {
  phase: AssistantPhase;
  text: string;
  steps: ToolStep[];
  sources: Source[];
  error: string;
};

type Action = { type: "start" } | { type: "quiet-over" } | { type: "event"; event: StreamEvent } | { type: "stop" } | { type: "reset" };

const INITIAL: State = { phase: "idle", text: "", steps: [], sources: [], error: "" };

const busy = (phase: AssistantPhase) => phase === "waiting" || phase === "thinking" || phase === "tool" || phase === "streaming";

const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "start":
      return { ...INITIAL, phase: "waiting" };
    case "quiet-over":
      return state.phase === "waiting" ? { ...state, phase: "thinking" } : state;
    case "stop":
      return busy(state.phase) ? { ...state, phase: "stopped", steps: state.steps.map((s) => (s.status === "running" ? { ...s, status: "failed", summary: "Stopped" } : s)) } : state;
    case "reset":
      return INITIAL;
    case "event": {
      if (!busy(state.phase)) return state; // a late event cannot move a settled response
      const e = action.event;
      switch (e.type) {
        case "text":
          return { ...state, phase: "streaming", text: state.text + e.text };
        case "tool_call":
          return { ...state, phase: "tool", steps: [...state.steps, { id: e.id, name: e.name, args: e.args, status: "running" }] };
        case "tool_result": {
          const sources = [...state.sources];
          for (const s of e.sources ?? []) if (!sources.some((x) => x.n === s.n)) sources.push(s);
          return {
            ...state,
            phase: "thinking",
            sources,
            steps: state.steps.map((s) => (s.id === e.id ? { ...s, status: e.ok ? "done" : "failed", summary: e.summary } : s)),
          };
        }
        case "error":
          return { ...state, phase: "error", error: e.message };
        case "done":
          return { ...state, phase: "done" };
      }
    }
  }
};

export interface AssistantOptions {
  quietMs?: number;
  slowMs?: number;
}

/**
 * Run a response through its states.
 *
 * @example
 * const a = useAssistant();
 * a.start(replay(recording, { speed: 3 }));
 */
export const useAssistant = ({ quietMs = QUIET_MS, slowMs = SLOW_MS }: AssistantOptions = {}) => {
  const [state, dispatch] = useReducer(reducer, INITIAL);
  const [stalledS, setStalledS] = useState(0);
  const controller = useRef<AbortController | null>(null);
  const run = useRef(0);
  const lastEventAt = useRef(0);
  const phaseRef = useRef(state.phase);
  useEffect(() => {
    phaseRef.current = state.phase;
  }, [state.phase]);

  const stop = useCallback(() => {
    run.current++;
    controller.current?.abort();
    dispatch({ type: "stop" });
  }, []);

  const reset = useCallback(() => {
    run.current++;
    controller.current?.abort();
    dispatch({ type: "reset" });
  }, []);

  const start = useCallback(
    (source: StreamSource) => {
      controller.current?.abort();
      const id = ++run.current;
      const ctl = new AbortController();
      controller.current = ctl;
      dispatch({ type: "start" });
      lastEventAt.current = performance.now();
      const quiet = window.setTimeout(() => id === run.current && dispatch({ type: "quiet-over" }), quietMs);
      (async () => {
        try {
          for await (const event of source(ctl.signal)) {
            if (id !== run.current) return;
            lastEventAt.current = performance.now();
            dispatch({ type: "event", event });
          }
        } catch (err) {
          if (id === run.current) dispatch({ type: "event", event: { t: 0, type: "error", message: err instanceof Error ? err.message : "Something went wrong." } });
        } finally {
          window.clearTimeout(quiet);
        }
      })();
    },
    [quietMs]
  );

  // How long since anything arrived, once that passes slowMs. Ticks only while busy.
  useEffect(() => {
    if (!busy(state.phase)) return;
    const timer = window.setInterval(() => {
      const quietFor = performance.now() - lastEventAt.current;
      setStalledS(quietFor >= slowMs ? Math.floor(quietFor / 1000) : 0);
    }, 250);
    return () => {
      window.clearInterval(timer);
      setStalledS(0);
    };
  }, [state.phase, slowMs]);

  useEffect(() => () => controller.current?.abort(), []);

  return { ...state, busy: busy(state.phase), stalledS, start, stop, reset };
};

"use client";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";

/**
 * Latency states: one honest lifecycle for anything that waits on a request.
 *
 * It is a state, not a component. The async button and the loading region
 * both run on it, and anything else that waits (a select that fetches its
 * options, a search box, a save bar) can take the same hook and get the same
 * timing rules for free:
 *
 * - pending: a request is out but under the skeleton threshold, so nothing
 *   new is drawn. A fast response never flashes a placeholder.
 * - skeleton: it has passed that threshold (only if you ask for one).
 * - slow: it has taken long enough that the interface should say so.
 * - success / error / cancelled: settled. START runs it again, RESET clears it.
 */
/** Under this, show nothing new: a fast response never flashes a placeholder. Shared by every waiting surface. */
export const QUIET_MS = 400;
/** Past this with no progress, say it is slow and offer a way out. */
export const SLOW_MS = 2000;

export type LatencyPhase = "idle" | "pending" | "skeleton" | "slow" | "success" | "error" | "cancelled";

export type LatencyEvent = "START" | "SHOW_SKELETON" | "SLOW" | "RESOLVE" | "REJECT" | "CANCEL" | "RESET";

/** Every legal transition. Anything not listed is ignored, so a late result cannot move a settled state. */
export const LATENCY_TRANSITIONS: Record<LatencyPhase, Partial<Record<LatencyEvent, LatencyPhase>>> = {
  idle: { START: "pending" },
  pending: { SHOW_SKELETON: "skeleton", SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  skeleton: { SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  slow: { RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  success: { START: "pending", RESET: "idle" },
  error: { START: "pending", RESET: "idle" },
  cancelled: { START: "pending", RESET: "idle" },
};

export const latencyReducer = (state: LatencyPhase, event: LatencyEvent): LatencyPhase =>
  LATENCY_TRANSITIONS[state][event] ?? state;

/**
 * The part of the machine one component uses: only these phases, reached
 * only by these events. A component that never shows a skeleton or never
 * cancels draws its own machine from this, and it is still the shared one.
 */
export const sliceTransitions = <P extends LatencyPhase, E extends LatencyEvent>(phases: readonly P[], events: readonly E[]) =>
  Object.fromEntries(
    phases.map((from) => [
      from,
      Object.fromEntries(
        Object.entries(LATENCY_TRANSITIONS[from]).filter(
          ([event, to]) => events.includes(event as E) && phases.includes(to as P)
        )
      ),
    ])
  ) as Record<P, Partial<Record<E, P>>>;

export const isBusy = (phase: LatencyPhase) => phase === "pending" || phase === "skeleton" || phase === "slow";

export interface LatencyLogEntry {
  /** Milliseconds since the request started (0 for START). */
  atMs: number;
  event: LatencyEvent;
  from: LatencyPhase;
  to: LatencyPhase;
}

export interface LatencyOptions<T> {
  /** The request. Honour `signal` if you can; late results are ignored either way. */
  run: (signal: AbortSignal) => Promise<T>;
  /** Show a skeleton after this long. Leave undefined to never show one. */
  skeletonAfterMs?: number;
  /** Say it is slow after this long. */
  slowAfterMs?: number;
  /** Return to idle this long after success. Leave undefined to stay on success. */
  successHoldMs?: number;
  /** Every real state change, with time since the request started. */
  onEvent?: (entry: LatencyLogEntry) => void;
}

/**
 * Run a request through the latency states.
 *
 * @example
 * const { phase, start } = useLatency({ run: (signal) => fetch("/api", { signal }), slowAfterMs: 1500 });
 */
export const useLatency = <T>({ run, skeletonAfterMs, slowAfterMs = SLOW_MS, successHoldMs, onEvent }: LatencyOptions<T>) => {
  const [phase, dispatch] = useReducer(latencyReducer, "idle");
  const phaseRef = useRef<LatencyPhase>("idle");
  const [data, setData] = useState<{ value: T } | null>(null);
  const [error, setError] = useState("");
  const [elapsedS, setElapsedS] = useState(0);

  const requestId = useRef(0);
  const startedAt = useRef(0);
  const timers = useRef<number[]>([]);
  const ticker = useRef<number | null>(null);
  const controller = useRef<AbortController | null>(null);
  const mounted = useRef(true);
  const onEventRef = useRef(onEvent);
  useEffect(() => {
    onEventRef.current = onEvent;
  }, [onEvent]);

  const stopTimers = () => {
    timers.current.forEach((t) => window.clearTimeout(t));
    timers.current = [];
    if (ticker.current !== null) window.clearInterval(ticker.current);
    ticker.current = null;
  };

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      stopTimers();
      controller.current?.abort();
    };
  }, []);

  /** Dispatch only legal events, and report real changes. */
  const send = useCallback((event: LatencyEvent) => {
    const from = phaseRef.current;
    const to = latencyReducer(from, event);
    if (to === from) return false;
    phaseRef.current = to;
    dispatch(event);
    const atMs = event === "START" ? 0 : Math.round(performance.now() - startedAt.current);
    onEventRef.current?.({ atMs, event, from, to });
    return true;
  }, []);

  const start = useCallback(() => {
    if (isBusy(phaseRef.current)) return;
    stopTimers();
    startedAt.current = performance.now();
    if (!send("START")) return;
    const id = ++requestId.current;
    const ctl = new AbortController();
    controller.current = ctl;
    const live = () => mounted.current && id === requestId.current;

    if (skeletonAfterMs !== undefined) {
      timers.current.push(window.setTimeout(() => live() && send("SHOW_SKELETON"), skeletonAfterMs));
    }
    timers.current.push(
      window.setTimeout(() => {
        if (!live()) return;
        send("SLOW");
        const tick = () => setElapsedS(Math.floor((performance.now() - startedAt.current) / 1000));
        tick();
        ticker.current = window.setInterval(tick, 250);
      }, slowAfterMs)
    );

    Promise.resolve()
      .then(() => run(ctl.signal))
      .then(
        (value) => {
          if (!live()) return;
          stopTimers();
          setData({ value });
          send("RESOLVE");
          if (successHoldMs !== undefined) {
            timers.current.push(window.setTimeout(() => live() && send("RESET"), successHoldMs));
          }
        },
        (err: unknown) => {
          if (!live()) return;
          stopTimers();
          setError(err instanceof Error ? err.message : "Request failed");
          send("REJECT");
        }
      );
  }, [run, send, skeletonAfterMs, slowAfterMs, successHoldMs]);

  const cancel = useCallback(() => {
    if (!isBusy(phaseRef.current)) return;
    requestId.current++; // a late result can no longer move the state
    stopTimers();
    controller.current?.abort();
    send("CANCEL");
  }, [send]);

  const reset = useCallback(() => {
    requestId.current++;
    stopTimers();
    send("RESET");
  }, [send]);

  return { phase, busy: isBusy(phase), data, error, elapsedS, start, cancel, reset };
};

"use client";
import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

let query: MediaQueryList | null = null;
const getQuery = () => {
  if (!query && typeof window !== "undefined") query = window.matchMedia(QUERY);
  return query;
};

/**
 * A simulated setting, used by X-ray mode so anyone can see what every
 * component does with reduced motion without changing their OS setting.
 * null means "follow the system".
 */
let simulated: boolean | null = null;
const simulationListeners = new Set<() => void>();

/** Override the system setting (true or false), or pass null to follow it again. */
export const simulateReducedMotion = (value: boolean | null) => {
  if (simulated === value) return;
  simulated = value;
  simulationListeners.forEach((notify) => notify());
};

/** Whether the reduced-motion setting is currently simulated rather than read from the system. */
export const reducedMotionSimulated = (): boolean => simulated !== null;

/**
 * Whether the user has asked for reduced motion, read live. Cheap enough to
 * call every frame inside a rAF loop, so the setting takes effect mid-animation.
 */
export const reducedMotionNow = (): boolean => simulated ?? getQuery()?.matches ?? false;

/**
 * Seconds to feed into time-based colour drift (`pastelColour`, `colourField`).
 * With reduced motion the clock stops, so colour still follows the user but no
 * longer drifts on its own.
 */
export const motionTime = (): number => (reducedMotionNow() ? 0 : performance.now() / 1000);

const subscribe = (notify: () => void) => {
  const q = getQuery();
  q?.addEventListener("change", notify);
  simulationListeners.add(notify);
  return () => {
    q?.removeEventListener("change", notify);
    simulationListeners.delete(notify);
  };
};

/** React hook for the same setting. The server snapshot is false, so first paint matches. */
export const useReducedMotion = (): boolean =>
  useSyncExternalStore(subscribe, reducedMotionNow, () => false);

"use client";
import { useId, useRef, type ReactNode } from "react";
import { X } from "lucide-react";
import { reducedMotionNow } from "../hooks/reduced-motion";
import { useModal, type DismissReason } from "../hooks/overlay";

export interface DialogProps {
  /** Whether it is open. */
  open: boolean;
  /** Called with false when it asks to close: Escape, the close button, or a press on the backdrop. */
  onOpenChange: (open: boolean, reason: DismissReason) => void;
  /** Names the dialog. Rendered as its heading. */
  title: string;
  /** Describes it, linked with aria-describedby. */
  description?: ReactNode;
  children?: ReactNode;
  /** Buttons along the bottom. Put `data-autofocus` on the one that should take focus first. */
  footer?: ReactNode;
  /**
   * "alertdialog" for confirmations that need an answer: a backdrop press does
   * not dismiss it, and there is no close button. Default: "dialog"
   */
  role?: "dialog" | "alertdialog";
  /** Panel width. Default: "md" */
  size?: "sm" | "md" | "lg";
  className?: string;
}

const WIDTH = { sm: "max-w-sm", md: "max-w-md", lg: "max-w-xl" } as const;

/**
 * A modal dialog built on the native `<dialog>` element and showModal(), so
 * the browser does what it is best at: the rest of the page becomes inert
 * (not just visually covered), and the dialog sits in the top layer above
 * every stacking context. Everything it cannot animate, Prism does: the
 * panel and backdrop spring in and out, and Escape is routed through the
 * spring rather than cutting it off.
 *
 * Focus moves to `data-autofocus` or the first control, and goes back to
 * whatever opened it once it has gone. The page behind does not scroll.
 *
 * @example
 * <Dialog
 *   open={open}
 *   onOpenChange={setOpen}
 *   role="alertdialog"
 *   title="Delete this project?"
 *   description="Its 12 files go with it. This cannot be undone."
 *   footer={<>
 *     <button data-autofocus onClick={() => setOpen(false)}>Cancel</button>
 *     <button onClick={remove}>Delete</button>
 *   </>}
 * />
 */
export const Dialog = ({ open, onOpenChange, title, description, children, footer, role = "dialog", size = "md", className = "" }: DialogProps) => {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const backdropRef = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const descId = useId();
  const alert = role === "alertdialog";

  const { mounted } = useModal({
    open,
    onDismiss: (reason) => onOpenChange(false, reason),
    dialogRef,
    panelRef,
    dismissOnOutside: !alert,
    render: (p) => {
      const panel = panelRef.current;
      const backdrop = backdropRef.current;
      const o = Math.min(1, Math.max(0, p));
      if (backdrop) backdrop.style.opacity = o.toFixed(3);
      if (!panel) return;
      panel.style.opacity = o.toFixed(3);
      panel.style.transform = reducedMotionNow() ? "none" : `translateY(${((1 - p) * 10).toFixed(2)}px) scale(${(0.965 + 0.035 * p).toFixed(4)})`;
      panel.style.pointerEvents = open ? "auto" : "none";
    },
  });

  if (!mounted) return null;

  return (
    <dialog
      ref={dialogRef}
      aria-labelledby={titleId}
      aria-describedby={description ? descId : undefined}
      role={alert ? "alertdialog" : undefined}
      className="fixed inset-0 m-0 h-full max-h-none w-full max-w-none overflow-y-auto bg-transparent p-0 text-white backdrop:bg-transparent"
    >
      <div ref={backdropRef} aria-hidden="true" className="fixed inset-0 bg-black/55 backdrop-blur-[2px]" style={{ opacity: 0 }} />
      <div className="relative flex min-h-full items-center justify-center p-4">
        <div
          ref={panelRef}
          className={`relative w-full ${WIDTH[size]} rounded-2xl border border-white/[0.1] bg-[#0b0b0b] p-6 shadow-[0_30px_80px_rgba(0,0,0,0.6)] ${className}`}
          style={{ opacity: 0 }}
        >
          <h2 id={titleId} className="pr-8 text-[17px] font-medium tracking-[-0.01em] text-white/95">
            {title}
          </h2>
          {description && (
            <div id={descId} className="mt-2 text-sm leading-relaxed text-white/60">
              {description}
            </div>
          )}
          {children && <div className="mt-5">{children}</div>}
          {footer && <div className="mt-6 flex flex-wrap justify-end gap-2">{footer}</div>}
          {!alert && (
            <button
              type="button"
              aria-label="Close"
              onClick={() => onOpenChange(false, "button")}
              className="absolute right-3 top-3 flex h-8 w-8 items-center justify-center rounded-lg text-white/50 transition-colors hover:bg-white/[0.06] hover:text-white/85 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
            >
              <X size={16} />
            </button>
          )}
        </div>
      </div>
    </dialog>
  );
};

"use client";
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type RefObject } from "react";

/**
 * The overlay layer: what every popover, menu, dialog, sheet and toast shares.
 *
 * - Springs that are integrated against real time, so a 120Hz screen moves
 *   them at the same speed as a 60Hz one.
 * - Presence: an overlay stays mounted until its exit spring has finished,
 *   then unmounts. Closing is never a cut.
 * - One dismiss stack: Escape closes the top layer only, and a click outside
 *   closes every layer that does not hold it, from the top down.
 * - Scroll lock and focus return for modals.
 *
 * Why not the browser's light dismiss? `popover="auto"` and `<dialog>` close
 * instantly, which leaves no room for an exit spring. So overlays use
 * `popover="manual"` for the top layer and do the dismissing here.
 */

// --- Springs ---------------------------------------------------------------

export type Spring = { k: number; d: number };
export type SpringState = { x: number; v: number };

/** The same constants the command palette and select use, so every overlay feels like one family. */
export const SPRINGS = {
  panel: { k: 200, d: 24 },
  indicator: { k: 180, d: 22 },
  stack: { k: 220, d: 26 },
} as const satisfies Record<string, Spring>;

/** Advance a spring by `dt` seconds, in fixed 1/120s substeps (semi-implicit Euler). */
export const stepSpring = (s: SpringState, target: number, { k, d }: Spring, dt: number) => {
  let left = Math.min(Math.max(dt, 0), 0.064); // a long pause (tab switch) does not fling it
  while (left > 0) {
    const h = Math.min(left, 1 / 120);
    s.v += (k * (target - s.x) - d * s.v) * h;
    s.x += s.v * h;
    left -= h;
  }
};

export const atRest = (s: SpringState, target: number, eps = 0.0005) =>
  Math.abs(target - s.x) < eps && Math.abs(s.v) < eps * 20;

// --- Presence --------------------------------------------------------------

/**
 * Keep something mounted while it animates out.
 *
 * `render(p)` is called every frame with progress from 0 (gone) to 1 (fully
 * present) and should write styles straight to the DOM, so nothing re-renders
 * per frame. Reversing mid-flight carries the velocity over.
 *
 * Returns `drive` and `kick` so a drag can move the progress by hand and
 * hand it back to the spring on release.
 */
export const usePresence = (open: boolean, render: (p: number) => void, spring: Spring = SPRINGS.panel) => {
  const [mounted, setMounted] = useState(open);
  if (open && !mounted) setMounted(true);

  const state = useRef<SpringState>({ x: 0, v: 0 });
  const raf = useRef(0);
  const openRef = useRef(open);
  const renderRef = useRef(render);
  useLayoutEffect(() => {
    renderRef.current = render;
    openRef.current = open;
  });

  const kick = useCallback(() => {
    if (raf.current) return;
    let last = performance.now();
    const tick = (now: number) => {
      const target = openRef.current ? 1 : 0;
      stepSpring(state.current, target, spring, (now - last) / 1000);
      last = now;
      // Leaving is done once it is invisible; there is no need to wait out the tail.
      const done = target === 1 ? atRest(state.current, 1) : state.current.x <= 0.01;
      if (done) state.current = { x: target, v: 0 };
      renderRef.current(state.current.x);
      if (done) {
        raf.current = 0;
        if (!openRef.current) setMounted(false);
        return;
      }
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, [spring]);

  useLayoutEffect(() => {
    if (!mounted) return;
    renderRef.current(state.current.x); // first frame before paint, so it never flashes in at full size
    kick();
  }, [open, mounted, kick]);

  useEffect(
    () => () => {
      cancelAnimationFrame(raf.current);
      raf.current = 0;
    },
    []
  );

  /** Set progress (and velocity, in progress per second) by hand. Call `kick` to let the spring carry on. */
  const drive = useCallback((x: number, v = 0) => {
    state.current = { x, v };
  }, []);

  return { mounted, drive, kick };
};

// --- Dismiss stack ---------------------------------------------------------

export type DismissReason = "escape" | "outside" | "focus-out" | "select" | "button";

type Layer = { contains: (node: Node) => boolean; dismiss: (reason: DismissReason) => void };

const layers: Layer[] = [];

const onKeyDown = (e: KeyboardEvent) => {
  if (e.key !== "Escape" || e.isComposing) return;
  const top = layers[layers.length - 1];
  if (!top) return;
  // Default-prevented, so a native dialog underneath does not also close.
  e.preventDefault();
  e.stopPropagation();
  top.dismiss("escape");
};

const onPointerDown = (e: PointerEvent) => {
  const target = e.target;
  if (!(target instanceof Node)) return;
  for (const layer of [...layers].reverse()) {
    if (layer.contains(target)) break;
    layer.dismiss("outside");
  }
};

const listen = (on: boolean) => {
  if (on) {
    window.addEventListener("keydown", onKeyDown, true);
    window.addEventListener("pointerdown", onPointerDown, true);
  } else {
    window.removeEventListener("keydown", onKeyDown, true);
    window.removeEventListener("pointerdown", onPointerDown, true);
  }
};

/**
 * Put a layer on the dismiss stack while `active`. Layers opened later sit
 * above earlier ones, so a menu inside a dialog closes before the dialog does.
 */
export const useDismissLayer = (active: boolean, contains: (node: Node) => boolean, dismiss: (reason: DismissReason) => void) => {
  const live = useRef({ contains, dismiss });
  useLayoutEffect(() => {
    live.current = { contains, dismiss };
  });
  useEffect(() => {
    if (!active) return;
    const layer: Layer = {
      contains: (node) => live.current.contains(node),
      dismiss: (reason) => live.current.dismiss(reason),
    };
    layers.push(layer);
    if (layers.length === 1) listen(true);
    return () => {
      const i = layers.indexOf(layer);
      if (i >= 0) layers.splice(i, 1);
      if (layers.length === 0) listen(false);
    };
  }, [active]);
};

// --- Focus -----------------------------------------------------------------

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';

export const focusablesIn = (root: Element | null): HTMLElement[] =>
  root ? [...root.querySelectorAll<HTMLElement>(FOCUSABLE)].filter((el) => el.getClientRects().length > 0) : [];

/** Focus `[data-autofocus]` if there is one, else the first focusable, else the root itself. */
export const focusInitial = (root: HTMLElement | null) => {
  if (!root) return;
  const el = root.querySelector<HTMLElement>("[data-autofocus]") ?? focusablesIn(root)[0] ?? root;
  el.focus({ preventScroll: true });
};

// --- Scroll lock -----------------------------------------------------------

let locks = 0;
let saved = { overflow: "", paddingRight: "" };

/** Stop the page scrolling behind a modal, without the layout jumping when the scrollbar goes. Nested locks count. */
export const lockScroll = () => {
  const html = document.documentElement;
  if (locks++ === 0) {
    const gap = window.innerWidth - html.clientWidth;
    saved = { overflow: html.style.overflow, paddingRight: html.style.paddingRight };
    html.style.overflow = "hidden";
    if (gap > 0) html.style.paddingRight = `${gap}px`;
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--locks === 0) {
      html.style.overflow = saved.overflow;
      html.style.paddingRight = saved.paddingRight;
    }
  };
};

// --- Modal -----------------------------------------------------------------

export interface ModalOptions {
  open: boolean;
  onDismiss: (reason: DismissReason) => void;
  dialogRef: RefObject<HTMLDialogElement | null>;
  /** The visible panel. A press anywhere else (the backdrop) is outside. */
  panelRef: RefObject<HTMLElement | null>;
  /** Whether a press on the backdrop dismisses. Off for confirmations. */
  dismissOnOutside?: boolean;
  render: (p: number) => void;
}

/**
 * A native `<dialog>` opened with showModal(), so the browser makes the rest
 * of the page inert and puts it in the top layer, with a spring on both ways.
 *
 * Focus moves to `[data-autofocus]` (or the first control) on open and back to
 * whatever opened it once it has gone.
 */
export const useModal = ({ open, onDismiss, dialogRef, panelRef, dismissOnOutside = true, render }: ModalOptions) => {
  const presence = usePresence(open, render);
  const { mounted } = presence;
  const onDismissRef = useRef(onDismiss);
  useLayoutEffect(() => {
    onDismissRef.current = onDismiss;
  });

  useLayoutEffect(() => {
    const dialog = dialogRef.current;
    if (!mounted || !dialog) return;
    const invoker = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const release = lockScroll();
    if (!dialog.open) dialog.showModal();
    focusInitial(panelRef.current);
    return () => {
      release();
      if (dialog.open) dialog.close();
      if (invoker?.isConnected) invoker.focus({ preventScroll: true });
    };
  }, [mounted, dialogRef, panelRef]);

  // The browser can still ask to close (Android back, a close watcher): route it through the spring.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!mounted || !dialog) return;
    const onCancel = (e: Event) => {
      e.preventDefault();
      onDismissRef.current("escape");
    };
    dialog.addEventListener("cancel", onCancel);
    return () => dialog.removeEventListener("cancel", onCancel);
  }, [mounted, dialogRef]);

  useDismissLayer(
    open,
    (node) => !!panelRef.current?.contains(node) || !dismissOnOutside,
    onDismiss
  );

  return presence;
};

"use client";
import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

let query: MediaQueryList | null = null;
const getQuery = () => {
  if (!query && typeof window !== "undefined") query = window.matchMedia(QUERY);
  return query;
};

/**
 * A simulated setting, used by X-ray mode so anyone can see what every
 * component does with reduced motion without changing their OS setting.
 * null means "follow the system".
 */
let simulated: boolean | null = null;
const simulationListeners = new Set<() => void>();

/** Override the system setting (true or false), or pass null to follow it again. */
export const simulateReducedMotion = (value: boolean | null) => {
  if (simulated === value) return;
  simulated = value;
  simulationListeners.forEach((notify) => notify());
};

/** Whether the reduced-motion setting is currently simulated rather than read from the system. */
export const reducedMotionSimulated = (): boolean => simulated !== null;

/**
 * Whether the user has asked for reduced motion, read live. Cheap enough to
 * call every frame inside a rAF loop, so the setting takes effect mid-animation.
 */
export const reducedMotionNow = (): boolean => simulated ?? getQuery()?.matches ?? false;

/**
 * Seconds to feed into time-based colour drift (`pastelColour`, `colourField`).
 * With reduced motion the clock stops, so colour still follows the user but no
 * longer drifts on its own.
 */
export const motionTime = (): number => (reducedMotionNow() ? 0 : performance.now() / 1000);

const subscribe = (notify: () => void) => {
  const q = getQuery();
  q?.addEventListener("change", notify);
  simulationListeners.add(notify);
  return () => {
    q?.removeEventListener("change", notify);
    simulationListeners.delete(notify);
  };
};

/** React hook for the same setting. The server snapshot is false, so first paint matches. */
export const useReducedMotion = (): boolean =>
  useSyncExternalStore(subscribe, reducedMotionNow, () => false);

"use client";
import { useId, useRef, type PointerEvent, type ReactNode } from "react";
import { X } from "lucide-react";
import { reducedMotionNow } from "../hooks/reduced-motion";
import { useModal, type DismissReason } from "../hooks/overlay";

export type SheetSide = "right" | "left" | "bottom";

export interface SheetProps {
  /** Whether it is open. */
  open: boolean;
  /** Called with false when it asks to close: Escape, the close button, the backdrop, or a drag past the threshold. */
  onOpenChange: (open: boolean, reason: DismissReason | "drag") => void;
  /** Names the sheet. Rendered as its heading. */
  title: string;
  /** Describes it, linked with aria-describedby. */
  description?: ReactNode;
  children?: ReactNode;
  /** Pinned to the bottom of the sheet. */
  footer?: ReactNode;
  /** Which edge it comes from. Default: "right" */
  side?: SheetSide;
  className?: string;
}

/** Fraction of its size a drag has to travel to close it. */
const CLOSE_AT = 0.3;
/** Or a flick faster than this, in px per ms. */
const FLICK = 0.5;

/**
 * A panel that slides in from an edge: settings, filters, a cart, a share
 * sheet on a phone. It is the same native modal as Dialog (inert page, top
 * layer, focus in and back, no scroll behind) with a different entrance.
 *
 * It can be dragged closed from its handle. The drag follows the finger one
 * to one, resists being pulled the wrong way, and on release the spring takes
 * over from exactly where the finger let go: past a third of the way or
 * flicked, it closes; otherwise it settles back.
 *
 * @example
 * <Sheet open={open} onOpenChange={setOpen} title="Filters" side="right">
 *   <FilterForm />
 * </Sheet>
 */
export const Sheet = ({ open, onOpenChange, title, description, children, footer, side = "right", className = "" }: SheetProps) => {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const backdropRef = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const descId = useId();
  const drag = useRef<{ id: number; start: number; last: number; lastT: number; v: number; offset: number } | null>(null);
  const vertical = side === "bottom";

  const size = () => {
    const panel = panelRef.current;
    return panel ? (vertical ? panel.offsetHeight : panel.offsetWidth) : 1;
  };

  /** Signed direction a closing sheet moves in. */
  const away = side === "left" ? -1 : 1;

  const paint = (p: number) => {
    // While a finger holds it, the drag owns the position and the spring waits.
    const d = drag.current;
    if (d) {
      p = 1 - d.offset / size();
      drive(p);
    }
    const panel = panelRef.current;
    const backdrop = backdropRef.current;
    const o = Math.min(1, Math.max(0, p));
    if (backdrop) backdrop.style.opacity = o.toFixed(3);
    if (!panel) return;
    const reduced = reducedMotionNow();
    // With reduced motion it fades in place instead of travelling.
    const shift = reduced ? 0 : (1 - p) * size() * away;
    panel.style.transform = vertical ? `translateY(${shift.toFixed(2)}px)` : `translateX(${shift.toFixed(2)}px)`;
    panel.style.opacity = reduced ? o.toFixed(3) : "1";
    panel.style.pointerEvents = open ? "auto" : "none";
  };

  const { mounted, drive, kick } = useModal({
    open,
    onDismiss: (reason) => onOpenChange(false, reason),
    dialogRef,
    panelRef,
    render: paint,
  });

  const along = (e: PointerEvent) => (vertical ? e.clientY : e.clientX);

  const onPointerDown = (e: PointerEvent<HTMLElement>) => {
    if (e.button !== 0 || !open) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    const at = along(e);
    drag.current = { id: e.pointerId, start: at, last: at, lastT: e.timeStamp, v: 0, offset: 0 };
  };

  const onPointerMove = (e: PointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    const at = along(e);
    const dt = Math.max(1, e.timeStamp - d.lastT);
    d.v = ((at - d.last) / dt) * away;
    d.last = at;
    d.lastT = e.timeStamp;
    const raw = (at - d.start) * away;
    // One to one towards closed; a stiff rubber band the other way.
    d.offset = raw >= 0 ? raw : -Math.sqrt(-raw) * 2;
    paint(1 - d.offset / size());
  };

  const onPointerUp = (e: PointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    drag.current = null;
    // Hand the drag's speed to the spring so the release has no seam.
    drive(1 - d.offset / size(), (-d.v * 1000) / size());
    if (d.offset > size() * CLOSE_AT || d.v > FLICK) onOpenChange(false, "drag");
    kick();
  };

  if (!mounted) return null;

  const edge = {
    right: "inset-y-0 right-0 h-full w-[min(420px,100vw)] rounded-l-2xl border-l",
    left: "inset-y-0 left-0 h-full w-[min(420px,100vw)] rounded-r-2xl border-r",
    // Full width on a phone, a centred column on anything wider.
    bottom: "inset-x-0 bottom-0 mx-auto max-h-[85vh] w-full max-w-xl rounded-t-3xl border-x border-t",
  }[side];

  const handle = (
    <div
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      className={`flex shrink-0 cursor-grab touch-none items-center justify-center active:cursor-grabbing ${
        vertical ? "h-7 w-full" : `absolute inset-y-0 ${side === "right" ? "left-0" : "right-0"} w-5`
      }`}
      aria-hidden="true"
    >
      <span className={`rounded-full bg-white/20 ${vertical ? "h-1 w-10" : "h-10 w-1"}`} />
    </div>
  );

  return (
    <dialog
      ref={dialogRef}
      aria-labelledby={titleId}
      aria-describedby={description ? descId : undefined}
      className="fixed inset-0 m-0 h-full max-h-none w-full max-w-none overflow-hidden bg-transparent p-0 text-white backdrop:bg-transparent"
    >
      <div ref={backdropRef} aria-hidden="true" className="fixed inset-0 bg-black/50" style={{ opacity: 0 }} />
      <div
        ref={panelRef}
        className={`fixed flex flex-col border-white/[0.1] bg-[#0b0b0b] shadow-[0_0_80px_rgba(0,0,0,0.6)] ${edge} ${className}`}
        style={{ transform: vertical ? "translateY(100%)" : `translateX(${away * 100}%)` }}
      >
        {handle}
        <div className={`flex items-start justify-between gap-4 px-6 ${vertical ? "pt-1" : "pt-6"}`}>
          <div>
            <h2 id={titleId} className="text-[17px] font-medium tracking-[-0.01em] text-white/95">
              {title}
            </h2>
            {description && (
              <div id={descId} className="mt-1.5 text-sm leading-relaxed text-white/55">
                {description}
              </div>
            )}
          </div>
          <button
            type="button"
            aria-label="Close"
            onClick={() => onOpenChange(false, "button")}
            className="-mr-2 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-white/50 transition-colors hover:bg-white/[0.06] hover:text-white/85 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
          >
            <X size={16} />
          </button>
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto px-6 py-5">{children}</div>
        {footer && <div className="flex justify-end gap-2 border-t border-white/[0.08] px-6 py-4">{footer}</div>}
      </div>
    </dialog>
  );
};

"use client";
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type RefObject } from "react";

/**
 * The overlay layer: what every popover, menu, dialog, sheet and toast shares.
 *
 * - Springs that are integrated against real time, so a 120Hz screen moves
 *   them at the same speed as a 60Hz one.
 * - Presence: an overlay stays mounted until its exit spring has finished,
 *   then unmounts. Closing is never a cut.
 * - One dismiss stack: Escape closes the top layer only, and a click outside
 *   closes every layer that does not hold it, from the top down.
 * - Scroll lock and focus return for modals.
 *
 * Why not the browser's light dismiss? `popover="auto"` and `<dialog>` close
 * instantly, which leaves no room for an exit spring. So overlays use
 * `popover="manual"` for the top layer and do the dismissing here.
 */

// --- Springs ---------------------------------------------------------------

export type Spring = { k: number; d: number };
export type SpringState = { x: number; v: number };

/** The same constants the command palette and select use, so every overlay feels like one family. */
export const SPRINGS = {
  panel: { k: 200, d: 24 },
  indicator: { k: 180, d: 22 },
  stack: { k: 220, d: 26 },
} as const satisfies Record<string, Spring>;

/** Advance a spring by `dt` seconds, in fixed 1/120s substeps (semi-implicit Euler). */
export const stepSpring = (s: SpringState, target: number, { k, d }: Spring, dt: number) => {
  let left = Math.min(Math.max(dt, 0), 0.064); // a long pause (tab switch) does not fling it
  while (left > 0) {
    const h = Math.min(left, 1 / 120);
    s.v += (k * (target - s.x) - d * s.v) * h;
    s.x += s.v * h;
    left -= h;
  }
};

export const atRest = (s: SpringState, target: number, eps = 0.0005) =>
  Math.abs(target - s.x) < eps && Math.abs(s.v) < eps * 20;

// --- Presence --------------------------------------------------------------

/**
 * Keep something mounted while it animates out.
 *
 * `render(p)` is called every frame with progress from 0 (gone) to 1 (fully
 * present) and should write styles straight to the DOM, so nothing re-renders
 * per frame. Reversing mid-flight carries the velocity over.
 *
 * Returns `drive` and `kick` so a drag can move the progress by hand and
 * hand it back to the spring on release.
 */
export const usePresence = (open: boolean, render: (p: number) => void, spring: Spring = SPRINGS.panel) => {
  const [mounted, setMounted] = useState(open);
  if (open && !mounted) setMounted(true);

  const state = useRef<SpringState>({ x: 0, v: 0 });
  const raf = useRef(0);
  const openRef = useRef(open);
  const renderRef = useRef(render);
  useLayoutEffect(() => {
    renderRef.current = render;
    openRef.current = open;
  });

  const kick = useCallback(() => {
    if (raf.current) return;
    let last = performance.now();
    const tick = (now: number) => {
      const target = openRef.current ? 1 : 0;
      stepSpring(state.current, target, spring, (now - last) / 1000);
      last = now;
      // Leaving is done once it is invisible; there is no need to wait out the tail.
      const done = target === 1 ? atRest(state.current, 1) : state.current.x <= 0.01;
      if (done) state.current = { x: target, v: 0 };
      renderRef.current(state.current.x);
      if (done) {
        raf.current = 0;
        if (!openRef.current) setMounted(false);
        return;
      }
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, [spring]);

  useLayoutEffect(() => {
    if (!mounted) return;
    renderRef.current(state.current.x); // first frame before paint, so it never flashes in at full size
    kick();
  }, [open, mounted, kick]);

  useEffect(
    () => () => {
      cancelAnimationFrame(raf.current);
      raf.current = 0;
    },
    []
  );

  /** Set progress (and velocity, in progress per second) by hand. Call `kick` to let the spring carry on. */
  const drive = useCallback((x: number, v = 0) => {
    state.current = { x, v };
  }, []);

  return { mounted, drive, kick };
};

